nextflow_code:
nextflow.enable.dsl=2

include { getSingleInput; getReference } from '../functions/parameters.nf'
include { extractKey } from '../functions/common.nf'
include { step_trimming__trimmomatic } from '../steps/step_trimming__trimmomatic'
include { step_mapping__bwa_mem2 } from '../steps/step_mapping__bwa_mem2'
include { step_variant__bcftools } from '../steps/step_variant__bcftools'

workflow module_staph_variants {
    take:
        reads
        reference

    main:
        trimmed = step_trimming__trimmomatic(reads).trimmed
        trimmed.cross(reference) { extractKey(it) }
            .multiMap {
                reads: it[0]
                refs:  it[1][1..3]
            }
            .set { ch }
        mapped = step_mapping__bwa_mem2(ch.reads, ch.refs)
        step_variant__bcftools(mapped.aligned_bam, ch.refs)

    emit:
        variants = step_variant__bcftools.out.variants
}

workflow {
    module_staph_variants(getSingleInput(), getReference('fa'))
}

nextflow.enable.dsl=2

// Synthetic template: Basic Illumina variant calling pipeline
include { step_qc__fastqc } from '../steps/step_qc__fastqc'
include { step_trimming__trimmomatic } from '../steps/step_trimming__trimmomatic'
include { step_mapping__bwa_mem2 } from '../steps/step_mapping__bwa_mem2'
include { step_variant__bcftools } from '../steps/step_variant__bcftools'
include { extractKey } from '../functions/common.nf'
include { getSingleInput; getReference } from '../functions/parameters.nf'

workflow module_illumina_variant_calling {
    take:
        reads
        reference

    main:
        step_qc__fastqc(reads)

        trimmed = step_trimming__trimmomatic(reads).trimmed

        trimmed.cross(reference) { extractKey(it) }
            .multiMap {
                reads: it[0]
                refs:  it[1][1..3]
            }
            .set { readsAndReferences }

        mapped = step_mapping__bwa_mem2(readsAndReferences.reads, readsAndReferences.refs)

        step_variant__bcftools(mapped.aligned_bam, readsAndReferences.refs)

    emit:
        variants = step_variant__bcftools.out.variants
}

workflow {
    module_illumina_variant_calling(getSingleInput(), getReference('fa'))
}

nextflow.enable.dsl=2

include { getSingleInput; getReference } from '../functions/parameters.nf'
include { extractKey } from '../functions/common.nf'
include { step_mapping__bwa_mem2 } from '../steps/step_mapping__bwa_mem2'
include { step_variant__bcftools } from '../steps/step_variant__bcftools'
include { step_assembly__spades } from '../steps/step_assembly__spades'
include { step_annotation__prokka } from '../steps/step_annotation__prokka'

workflow module_dual_analysis {
    take:
        trimmed_reads
        reference

    main:
        // Branch A: Reference-based variant calling
        trimmed_reads.cross(reference) { extractKey(it) }
            .multiMap {
                reads: it[0]
                refs:  it[1][1..3]
            }
            .set { ch }
        mapped = step_mapping__bwa_mem2(ch.reads, ch.refs)
        step_variant__bcftools(mapped.aligned_bam, ch.refs)

        // Branch B: De novo assembly + annotation
        assembled = step_assembly__spades(trimmed_reads).assembly
        step_annotation__prokka(assembled)

    emit:
        variants = step_variant__bcftools.out.variants
        assembly = assembled
}

workflow {
    module_dual_analysis(getSingleInput(), getReference('fa'))
}
